<?php
// ===== API nội bộ (Roblox + lưu Gmail) — gộp chung trong 1 file =====
if (isset($_GET['api'])) {
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store');

    function out($arr, $code = 200) {
        http_response_code($code);
        echo json_encode($arr, JSON_UNESCAPED_UNICODE);
        exit;
    }

    function rbx($url, $body = null) {
        $ch = curl_init($url);
        $headers = array('Accept: application/json');
        $opts = array(
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT        => 15,
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_USERAGENT      => 'Mozilla/5.0 (compatible; SQCTWeb/1.0)',
        );
        if ($body !== null) {
            $headers[] = 'Content-Type: application/json';
            $opts[CURLOPT_POST] = true;
            $opts[CURLOPT_POSTFIELDS] = json_encode($body);
        }
        $opts[CURLOPT_HTTPHEADER] = $headers;
        curl_setopt_array($ch, $opts);
        $res  = curl_exec($ch);
        $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);
        return array('code' => $code, 'data' => ($res === false ? null : json_decode($res, true)));
    }

    // ---- Tra cứu Roblox ----
    if ($_GET['api'] === 'roblox') {
        $name = isset($_GET['name']) ? $_GET['name'] : '';
        if (!preg_match('/^[A-Za-z0-9_]{3,20}$/', $name)) out(array('error' => 'Tên Roblox không hợp lệ.'), 400);

        $r = rbx('https://users.roblox.com/v1/usernames/users', array('usernames' => array($name), 'excludeBannedUsers' => false));
        if ($r['code'] === 429) out(array('error' => 'Roblox đang giới hạn truy cập. Hãy thử lại sau vài phút.'), 429);
        if ($r['data'] === null) out(array('error' => 'Không kết nối được tới Roblox từ máy chủ host.'), 502);
        if (empty($r['data']['data'][0])) out(array('error' => 'Không tìm thấy người chơi này.'), 404);
        $id = (int)$r['data']['data'][0]['id'];

        $u = rbx("https://users.roblox.com/v1/users/$id");
        if ($u['data'] === null) out(array('error' => 'Không lấy được thông tin tài khoản.'), 502);

        $g = rbx("https://groups.roblox.com/v2/users/$id/groups/roles");
        $roles = isset($g['data']['data']) ? $g['data']['data'] : array();

        $av = rbx("https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds=$id&size=150x150&format=Png&isCircular=false");
        $avatar = isset($av['data']['data'][0]['imageUrl']) ? $av['data']['data'][0]['imageUrl'] : '';

        $ids = array();
        foreach ($roles as $row) $ids[] = $row['group']['id'];
        $icons = array();
        foreach (array_chunk($ids, 100) as $chunk) {
            $ic = rbx('https://thumbnails.roblox.com/v1/groups/icons?groupIds=' . implode(',', $chunk) . '&size=150x150&format=Png&isCircular=false');
            if (isset($ic['data']['data'])) {
                foreach ($ic['data']['data'] as $row) {
                    $icons[$row['targetId']] = isset($row['imageUrl']) ? $row['imageUrl'] : '';
                }
            }
        }

        $groups = array();
        foreach ($roles as $row) {
            $gid = $row['group']['id'];
            $groups[] = array(
                'id'   => $gid,
                'name' => $row['group']['name'],
                'role' => $row['role']['name'],
                'rank' => $row['role']['rank'],
                'icon' => isset($icons[$gid]) ? $icons[$gid] : '',
            );
        }
        usort($groups, function ($a, $b) { return $b['rank'] - $a['rank']; });

        out(array(
            'id'          => $id,
            'name'        => $u['data']['name'],
            'displayName' => $u['data']['displayName'],
            'created'     => $u['data']['created'],
            'isBanned'    => !empty($u['data']['isBanned']),
            'avatar'      => $avatar,
            'groups'      => $groups,
        ));
    }

    // ---- Lưu tên + Gmail ----
    if ($_GET['api'] === 'save') {
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') out(array('ok' => false), 405);
        $in    = json_decode(file_get_contents('php://input'), true);
        if (!is_array($in)) $in = array();
        $name  = trim(preg_replace('/\s+/', ' ', isset($in['name']) ? (string)$in['name'] : ''));
        $email = strtolower(trim(isset($in['email']) ? (string)$in['email'] : ''));
        if (strlen($name) < 2 || strlen($name) > 120 || !preg_match('/^[a-z0-9._%+-]+@gmail\.com$/', $email)) {
            out(array('ok' => false, 'error' => 'invalid'), 400);
        }
        if (preg_match('/^[=+\-@]/', $name)) $name = "'" . $name;

        $dir = __DIR__ . '/data';
        if (!is_dir($dir)) {
            @mkdir($dir, 0755, true);
            @file_put_contents($dir . '/.htaccess',
                "<IfModule mod_authz_core.c>\nRequire all denied\n</IfModule>\n<IfModule !mod_authz_core.c>\nDeny from all\n</IfModule>\n");
        }
        $fh = @fopen($dir . '/users.csv', 'a');
        if ($fh) {
            if (flock($fh, LOCK_EX)) {
                fputcsv($fh, array(date('Y-m-d H:i:s'), $name, $email));
                flock($fh, LOCK_UN);
            }
            fclose($fh);
        }
        out(array('ok' => true));
    }


    // ---- Tin tức (Quân đội VN + TSQCT) qua Google News RSS ----
    if ($_GET['api'] === 'news') {
        $feeds = array(
            'army'  => '(site:qdnd.vn OR site:mod.gov.vn OR site:qpvn.vn) when:14d',
            'tsqct' => '"Trường Sĩ quan Chính trị" OR "Đại học Chính trị" OR "Trường Đại học Chính trị" when:60d',
        );
        $key = isset($_GET['f']) ? (string)$_GET['f'] : '';
        if (!isset($feeds[$key])) out(array('error' => 'feed'), 400);

        $dir = __DIR__ . '/data';
        if (!is_dir($dir)) {
            @mkdir($dir, 0755, true);
            @file_put_contents($dir . '/.htaccess',
                "<IfModule mod_authz_core.c>\nRequire all denied\n</IfModule>\n<IfModule !mod_authz_core.c>\nDeny from all\n</IfModule>\n");
        }
        $cache = $dir . '/news_' . $key . '.json';
        if (is_file($cache) && time() - filemtime($cache) < 600) { readfile($cache); exit; }

        $url = 'https://news.google.com/rss/search?q=' . rawurlencode($feeds[$key]) . '&hl=vi&gl=VN&ceid=VN:vi';
        $xml = false; $code = 0;
        if (function_exists('curl_init')) {
            $ch = curl_init($url);
            curl_setopt_array($ch, array(
                CURLOPT_RETURNTRANSFER => true,
                CURLOPT_TIMEOUT        => 12,
                CURLOPT_FOLLOWLOCATION => true,
                CURLOPT_USERAGENT      => 'Mozilla/5.0 (compatible; SQCTWeb/1.0)',
            ));
            $xml  = curl_exec($ch);
            $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
            curl_close($ch);
        }
        $items = array();
        if ($xml !== false && $code === 200 && function_exists('simplexml_load_string')) {
            libxml_use_internal_errors(true);
            $doc = simplexml_load_string($xml);
            if ($doc && isset($doc->channel->item)) {
                foreach ($doc->channel->item as $it) {
                    $t = strtotime((string)$it->pubDate);
                    $items[] = array(
                        'title'  => (string)$it->title,
                        'source' => (string)$it->source,
                        'link'   => (string)$it->link,
                        'time'   => $t ? $t * 1000 : 0,
                    );
                }
            }
        }
        if (!$items) {
            if (is_file($cache)) { readfile($cache); exit; }
            out(array('error' => 'Không lấy được tin từ máy chủ.'), 502);
        }
        $json = json_encode(array('items' => $items), JSON_UNESCAPED_UNICODE);
        @file_put_contents($cache, $json, LOCK_EX);
        echo $json;
        exit;
    }

    out(array('error' => 'unknown'), 404);
}
header('Cache-Control: no-cache, no-store, must-revalidate');
header('Pragma: no-cache');
?>
