<style>
:root{
  --bgimg:url("data:image/png;base64,");
  --red:#c8102e; --red-d:#8f0b20; --gold:#ffd23f;
  --text:#fff; --muted:rgba(255,255,255,.74); --line:rgba(255,255,255,.16);
  --glass:rgba(24,12,15,.68);
}
*{box-sizing:border-box}
html,body{height:100%;margin:0}
body{
  font-family:"Be Vietnam Pro",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
  color:var(--text); background:#160c0e; line-height:1.5;
}
[hidden]{display:none!important}

/* Ảnh nền full màn hình */
.bg{position:fixed;inset:0;z-index:0;overflow:hidden;background:#3a0710}
.bg::before{content:"";position:absolute;inset:-60px;background:var(--bgimg) center/cover no-repeat;filter:blur(48px) brightness(.45) saturate(1.4)}
.bg::after{
  content:"";position:absolute;inset:0;
  background:
    var(--bgimg) center 4vh/min(88vw,36dvh) no-repeat,
    linear-gradient(to top,rgba(10,4,6,.65),transparent 55%);
}
@media (min-width:900px){
  .bg::after{
    background:
      var(--bgimg) 12% center/min(72dvh,46vw) no-repeat,
      linear-gradient(to left,rgba(10,4,6,.5),transparent 55%);
  }
}

.stage{
  position:relative;z-index:1;min-height:100dvh;display:flex;
  align-items:flex-end;justify-content:center;
  padding:12px 12px max(12px,env(safe-area-inset-bottom));
}
@media (min-width:900px){
  .stage{align-items:center;justify-content:flex-end;padding:32px 6vw}
}

.panel{
  width:100%;max-width:460px;max-height:calc(100dvh - 24px);
  display:flex;flex-direction:column;overflow:hidden;
  background:var(--glass);
  -webkit-backdrop-filter:blur(18px) saturate(1.2);backdrop-filter:blur(18px) saturate(1.2);
  border:1px solid var(--line);border-radius:22px;
  box-shadow:0 20px 60px rgba(0,0,0,.45);
}
@media (min-width:900px){.panel{max-height:calc(100dvh - 64px)}}

.brand{display:flex;align-items:center;gap:12px;padding:14px 18px;border-bottom:1px solid var(--line)}
.brand img{width:44px;height:44px;flex:none}
.brand strong{display:block;font-size:15px;font-weight:600;line-height:1.25}
.brand span{display:block;font-size:13px;color:var(--gold)}

/* Thanh chuyển bảng */
.tabs{display:grid;grid-template-columns:repeat(5,1fr);border-bottom:1px solid var(--line)}
.tab{
  appearance:none;background:none;border:0;color:var(--muted);font:inherit;font-size:12px;
  padding:10px 4px 9px;display:flex;flex-direction:column;align-items:center;gap:5px;cursor:pointer;
  border-bottom:2px solid transparent;transition:color .15s,background .15s;
}
.tab:hover{background:rgba(255,255,255,.06);color:#fff}
.tab[aria-current="step"]{color:#fff;border-bottom-color:var(--gold);background:rgba(255,255,255,.07)}

/* Ô logo của từng ứng dụng */
.tile{display:inline-grid;place-items:center;border-radius:10px;color:#fff;font-weight:700;flex:none}
.tile img{width:58%;height:58%;object-fit:contain;display:block}
.tile.sm{width:30px;height:30px;font-size:14px}
.tile.lg{width:64px;height:64px;border-radius:16px;font-size:28px}
.tile.discord{background:#5865F2}
.tile.roblox{background:#2b2d31}
.tile.trello{background:#0c66e4}
.tile.cake{background:linear-gradient(135deg,var(--red),var(--red-d))}
.tile.ban{background:linear-gradient(135deg,#3a1010,#7a1f1f)}
.tile.gform{background:transparent;border-radius:0}
.tile.gform svg{width:100%;height:100%;display:block}

/* Vùng nội dung có thanh kéo */
.views{flex:1;min-height:0;overflow-y:auto;padding:18px;scrollbar-width:thin;scrollbar-color:var(--gold) transparent}
.views::-webkit-scrollbar,.groups::-webkit-scrollbar{width:8px}
.views::-webkit-scrollbar-thumb,.groups::-webkit-scrollbar-thumb{background:var(--gold);border-radius:8px}
.views::-webkit-scrollbar-track,.groups::-webkit-scrollbar-track{background:rgba(255,255,255,.06);border-radius:8px}

h1,h2{margin:0}
h2{font-size:20px;font-weight:700;line-height:1.3}
p{margin:0}
.lead{color:var(--muted);font-size:14px;margin-top:6px}
.head{display:flex;gap:14px;align-items:center;margin-bottom:16px}

.btn{
  appearance:none;border:0;font:inherit;font-weight:600;font-size:15px;cursor:pointer;
  display:inline-flex;align-items:center;justify-content:center;gap:8px;text-decoration:none;
  height:48px;padding:0 20px;border-radius:12px;color:#fff;
  background:linear-gradient(135deg,var(--red),var(--red-d));
  transition:filter .15s,transform .05s;
}
.btn:hover{filter:brightness(1.15)}
.btn:active{transform:translateY(1px)}
.btn.block{width:100%}
.btn.ghost{background:rgba(255,255,255,.1);border:1px solid var(--line)}
.btn:disabled{opacity:.5;cursor:not-allowed;filter:none}
a:focus-visible,button:focus-visible,input:focus-visible{outline:2px solid var(--gold);outline-offset:2px}

label{display:block;font-size:13px;color:var(--muted);margin:14px 0 6px}
input{
  width:100%;height:48px;padding:0 14px;font:inherit;font-size:15px;color:#fff;
  background:rgba(255,255,255,.08);border:1px solid var(--line);border-radius:12px;
}
input::placeholder{color:rgba(255,255,255,.4)}
input:focus{border-color:var(--gold);outline:none}
.note{font-size:12.5px;color:var(--muted);margin-top:12px}
.err{color:#ffb4b4;font-size:13.5px;margin-top:12px;min-height:1.2em}
.gate .btn{margin-top:16px}

/* Roblox */
.search{display:flex;gap:8px}
.search input{flex:1;min-width:0}
.search .btn{padding:0 16px}
.result{margin-top:16px}
.who{display:flex;gap:14px;align-items:center}
