.badge{display:inline-block;margin-left:6px;padding:1px 8px;border-radius:99px;background:#7a1f1f;color:#ffd6d6;font-size:12px}
.facts{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:14px 0}
.fact{background:rgba(255,255,255,.07);border:1px solid var(--line);border-radius:12px;padding:10px 12px;min-width:0}
.fact.wide{grid-column:1/-1}
