/* Tin tức mới nhất */
.views{min-height:110px}
.news{flex:none;display:flex;flex-direction:column;border-top:1px solid var(--line);background:rgba(0,0,0,.2);max-height:min(30dvh,280px)}
.news-head{display:flex;align-items:center;gap:8px;padding:10px 12px 8px 16px}
.news-head strong{font-size:14px;font-weight:600;flex:none}
.chips{display:flex;gap:6px;flex:1;min-width:0;overflow-x:auto;scrollbar-width:none}
.chips::-webkit-scrollbar{display:none}
.chip{appearance:none;font:inherit;font-size:12px;color:var(--muted);background:rgba(255,255,255,.08);border:1px solid var(--line);border-radius:99px;padding:3px 10px;cursor:pointer;white-space:nowrap}
.chip[aria-pressed="true"]{color:#2a1a00;background:var(--gold);border-color:var(--gold);font-weight:600}
.icon-btn{appearance:none;flex:none;width:32px;height:32px;display:grid;place-items:center;color:#fff;background:rgba(255,255,255,.08);border:1px solid var(--line);border-radius:10px;font-size:16px;line-height:1;cursor:pointer;transition:transform .2s}
.icon-btn:hover{background:rgba(255,255,255,.16)}
.icon-btn.spin{animation:nspin .9s linear infinite}
@keyframes nspin{to{transform:rotate(360deg)}}
#news-toggle[aria-expanded="false"]{transform:rotate(180deg)}
.news[data-collapsed="true"]{max-height:none}
.news[data-collapsed="true"] .chips,.news[data-collapsed="true"] .news-list,.news[data-collapsed="true"] .news-foot{display:none}
