.news-list::-webkit-scrollbar{width:8px}
.news-list::-webkit-scrollbar-thumb{background:var(--gold);border-radius:8px}
.news-list::-webkit-scrollbar-track{background:rgba(255,255,255,.06);border-radius:8px}
.news-list li{margin:0 0 6px}
.news-item{display:block;color:#fff;text-decoration:none;background:rgba(255,255,255,.06);border:1px solid var(--line);border-radius:12px;padding:9px 11px}
.news-item:hover{background:rgba(255,255,255,.11)}
.n-title{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;font-size:13.5px;font-weight:600;line-height:1.4}
.n-meta{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-top:6px;font-size:12px;color:var(--muted)}
.n-src{color:var(--gold);font-weight:600;overflow-wrap:anywhere}
.n-tag{padding:0 7px;border-radius:99px;background:rgba(255,255,255,.12);font-size:11px;color:#fff}
.n-time{width:100%;font-size:12px;color:var(--muted)}
.news-msg{color:var(--muted);font-size:13.5px;padding:8px 4px}
.news-msg .btn{height:38px;font-size:13.5px;margin:8px 8px 0 0;padding:0 14px}
.news-foot{margin:0;padding:6px 16px 9px;font-size:11.5px;color:var(--muted);border-top:1px solid var(--line)}
.pager{display:flex;gap:10px;padding:12px 18px;border-top:1px solid var(--line)}
.pager .btn{flex:1;height:44px}


@media (prefers-reduced-motion:reduce){*{transition:none!important}.icon-btn.spin{animation:none}}
</style>
</head>
