          <div><h2>Tham gia server Discord</h2></div>
        </div>
        <p class="lead" style="margin:0 0 18px">Vào server để nhận thông báo và trò chuyện cùng mọi người.</p>
        <a class="btn block" style="background:#5865F2" href="https://discord.gg/VS3Yqvv9z5" target="_blank" rel="noopener noreferrer">Tham gia server</a>
      </section>

      <!-- Tra cứu Roblox -->
      <section id="v-roblox" hidden>
        <div class="head">
          <span class="tile lg roblox"><img src="https://cdn.simpleicons.org/roblox/ffffff" alt="Roblox" onerror="this.replaceWith('R')"></span>
