        <a class="btn block" style="background:#0c66e4" href="https://trello.com/invite/b/6aae00297d7659a43dee672d/ATTIcc86703ff5a92fadd4e66d9e0dbda1fbB916D76F/:newspaper:-trường-si-quan-chinh-trị-tin-tức" target="_blank" rel="noopener noreferrer">Mở bảng Trello</a>
      </section>

      <!-- Tố cáo học viện -->
      <section id="v-report" hidden>
        <div class="head">
          <span class="tile lg gform"><svg viewBox="0 0 48 48" aria-hidden="true"><path fill="#673AB7" d="M37 45H11a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3h19l10 10v29a3 3 0 0 1-3 3z"/><path fill="#B39DDB" d="M30 3v7a3 3 0 0 0 3 3h7z"/><circle cx="16" cy="24" r="2" fill="#fff"/><rect x="21" y="22.2" width="13" height="3.6" rx="1.8" fill="#fff"/><circle cx="16" cy="31" r="2" fill="#fff"/><rect x="21" y="29.2" width="13" height="3.6" rx="1.8" fill="#fff"/><circle cx="16" cy="38" r="2" fill="#fff"/><rect x="21" y="36.2" width="13" height="3.6" rx="1.8" fill="#fff"/></svg></span>
          <div><h2>Tố cáo học viện</h2></div>
