</main>

<script>
const $ = s => document.querySelector(s);
const STEPS = ['discord','roblox','blacklist','trello','report'];
const tabs = [...document.querySelectorAll('.tab')];
let cur = 0;

/* ---------- Chuyển bảng ---------- */
function show(i){
  cur = i;
  STEPS.forEach((s,k) => {
    $('#v-'+s).hidden = k !== i;
    tabs[k].setAttribute('aria-current', k === i ? 'step' : 'false');
  });
  $('#prev').disabled = i === 0;
  $('#next').hidden = i === STEPS.length - 1;
  $('#views').scrollTop = 0;
  if (STEPS[i] === 'blacklist') renderBlacklist();
}
tabs.forEach(t => t.addEventListener('click', () => show(+t.dataset.i)));
$('#prev').addEventListener('click', () => show(Math.max(0, cur-1)));
$('#next').addEventListener('click', () => show(Math.min(STEPS.length-1, cur+1)));

/* ---------- Cổng nhập tên + Gmail ---------- */
function enter(user){
  $('#v-gate').hidden = true;
  $('#tabs').hidden = false;
  $('#pager').hidden = false;
  $('#news').hidden = false;
  setTimeout(initNews, 0);
  $('#hello').textContent = 'Xin chào, ' + user.name;
  show(0);
}
try {
  const saved = JSON.parse(sessionStorage.getItem('sqct_user') || 'null');
  if (saved && saved.name && saved.email) enter(saved);
} catch(e){}

$('#v-gate').addEventListener('submit', async e => {
  e.preventDefault();
  const name = $('#g-name').value.trim().replace(/\s+/g,' ');
  const email = $('#g-mail').value.trim().toLowerCase();
  const err = $('#g-err');
  if (name.length < 2) { err.textContent = 'Hãy nhập tên của bạn (ít nhất 2 ký tự).'; return; }
  if (!/^[a-z0-9._%+-]+@gmail\.com$/.test(email)) { err.textContent = 'Hãy nhập đúng địa chỉ Gmail, ví dụ ban@gmail.com.'; return; }
  err.textContent = '';
  const btn = $('#g-btn'); btn.disabled = true; btn.textContent = 'Đang vào…';
  try {
    await Promise.race([
      fetch('?api=save', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({name,email})}),
      new Promise(r => setTimeout(r, 4000))
    ]);
  } catch(e){}
  const user = {name,email};
  try { sessionStorage.setItem('sqct_user', JSON.stringify(user)); } catch(e){}
  enter(user);
});

/* ---------- Tra cứu Roblox ---------- */
function el(tag, cls, text){
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text !== undefined) n.textContent = text;
  return n;
}
function fact(label, value, wide){
  const f = el('div', 'fact' + (wide ? ' wide' : ''));
  f.append(el('small', '', label));
  const b = el('b', '', value);
  f.append(b);
  return f;
}
function render(d){
  const box = $('#rb-result');
  box.replaceChildren();

  const who = el('div', 'who');
  const av = el('img'); av.src = d.avatar || ''; av.alt = 'Ảnh đại diện ' + d.name;
  const t = el('div');
  const h = el('h3', '', d.displayName);
  if (d.isBanned) h.append(el('span', 'badge', 'Đã bị cấm'));
  t.append(h, el('small', '', '@' + d.name));
  who.append(av, t);

  const created = new Date(d.created);
  const days = Math.max(0, Math.floor((Date.now() - created) / 864e5));
  const y = Math.floor(days / 365), m = Math.floor((days % 365) / 30);
  const age = y ? `${y} năm${m ? ' ' + m + ' tháng' : ''}` : `${m} tháng`;

  const facts = el('div', 'facts');
  const idF = fact('ID', String(d.id));
  const cp = el('button', '', 'Sao chép'); cp.type = 'button';
  cp.addEventListener('click', async () => {
    try { await navigator.clipboard.writeText(String(d.id)); cp.textContent = 'Đã chép'; }
    catch(e){ cp.textContent = 'Không chép được'; }
    setTimeout(() => cp.textContent = 'Sao chép', 1500);
  });
  idF.querySelector('b').after(cp);
  facts.append(
    idF,
    fact('Số nhóm', String(d.groups.length)),
    fact('Ngày tạo tài khoản', created.toLocaleDateString('vi-VN')),
    fact('Đã tạo được', `${days.toLocaleString('vi-VN')} ngày (${age})`)
  );

  box.append(who, facts, el('p', 'groups-title', `Nhóm và rank (${d.groups.length})`));

  if (!d.groups.length) {
    box.append(el('p', 'empty', 'Người này chưa vào nhóm nào, hoặc danh sách nhóm đang ẩn.'));
  } else {
    const list = el('div', 'groups');
    d.groups.forEach(g => {
      const row = el('div', 'group');
      const ic = el('img'); ic.src = g.icon || ''; ic.alt = ''; ic.loading = 'lazy';
      const info = el('div', 'info');
      info.append(el('b', '', g.name), el('span', '', g.role));
      row.append(ic, info, el('span', 'rank', 'Rank ' + g.rank));
      list.append(row);
    });
    box.append(list);
  }
  box.hidden = false;
}

$('#rb-form').addEventListener('submit', async e => {
  e.preventDefault();
  const name = $('#rb-name').value.trim();
  const err = $('#rb-err'), btn = $('#rb-btn');
  if (!/^[A-Za-z0-9_]{3,20}$/.test(name)) {
    err.textContent = 'Tên Roblox gồm 3–20 ký tự: chữ, số hoặc dấu gạch dưới.';
    return;
  }
  err.textContent = ''; btn.disabled = true; btn.textContent = 'Đang tìm…';
  try {
    const r = await fetch('?api=roblox&name=' + encodeURIComponent(name));
    const text = await r.text();
    let d;
    try { d = JSON.parse(text); }
    catch(_) { throw new Error('Không nhận được dữ liệu. Hãy kiểm tra file index.php đã được tải lên host chưa.'); }
    if (d.error) throw new Error(d.error);
    render(d);
  } catch(ex) {
    $('#rb-result').hidden = true;
    err.textContent = ex.message;
  } finally {
    btn.disabled = false; btn.textContent = 'Tra cứu';
  }
});

/* ---------- Blacklist ---------- */
async function robloxLookup(name){
  const r = await fetch('?api=roblox&name=' + encodeURIComponent(name));
  let d; try { d = await r.json(); } catch(_) { throw new Error('Không nhận được dữ liệu từ máy chủ.'); }
  if (d.error) throw new Error(d.error);
  return d;
}
// 100 ô, tự set tên trong code thì mới hiện ra ngoài UI (ô trống sẽ tự ẩn)
const BLACKLIST = Array.from({length: 100}, () => ({roblox: '', discord: ''}));
BLACKLIST[0] = {roblox: '2002tin', discord: '1444178465434632292'};
// Cách thêm người khác: BLACKLIST[1] = {roblox: 'tenRoblox', discord: 'idDiscord'};

function blAvatar(e){
  return e.discord ? `https://unavatar.io/discord/${e.discord}` : `https://ui-avatars.com/api/?background=7a1f1f&color=fff&name=${encodeURIComponent(e.roblox || e.discord || '?')}`;
}
function blFacts(e){
  const f = el('div', 'facts');
  if (e._data) {
    const x = e._data;
    f.append(fact('ID Roblox', String(x.id)), fact('Ngày tạo', new Date(x.created).toLocaleDateString('vi-VN')), fact('Số nhóm', String(x.groups.length)));
  } else if (e.roblox) f.append(fact('Roblox', 'Đang tải…'));
  if (e.discord) f.append(fact('Discord ID', e.discord));
  return f;
}
function blToggle(row, e, av){
  const old = row.querySelector('.bl-detail');
  if (old) { old.remove(); return; }
  const d = el('div', 'bl-detail'); d.append(blFacts(e)); row.append(d);
  if (e.roblox && !e._data) {
    robloxLookup(e.roblox).then(x => {
      e._data = x; if (x.avatar) av.src = x.avatar;
      if (row.contains(d)) d.replaceChildren(blFacts(e));
    }).catch(ex => { if (row.contains(d)) d.replaceChildren(el('p', 'empty', ex.message)); });
  }
}
let blStarted = false;
function renderBlacklist(){
  if (blStarted) return; blStarted = true;
  const box = $('#bl-list'), list = BLACKLIST.filter(e => e.roblox || e.discord);
  if (!list.length) { box.append(el('p', 'empty', 'Danh sách đang trống.')); return; }
  list.forEach(e => {
    const row = el('div', 'bl-row'), top = el('div', 'bl-top');
    const av = el('img'); av.loading = 'lazy'; av.alt = ''; av.src = blAvatar(e);
    const info = el('div');
    info.append(el('b', '', e.roblox ? '@' + e.roblox : 'Discord: ' + e.discord));
    if (e.roblox && e.discord) info.append(el('small', '', 'Discord: ' + e.discord));
    top.append(av, info); row.append(top);
    row.addEventListener('click', () => blToggle(row, e, av));
    box.append(row);
    if (e.roblox) robloxLookup(e.roblox).then(x => { e._data = x; if (x.avatar) av.src = x.avatar; }).catch(() => {});
  });
}

/* ---------- Tin tức mới nhất (Quân đội VN + TSQCT) ---------- */
const NEWS_KEY = 'sqct_news_v1', NEWS_TTL = 10*60*1000;
const NEWS_FEEDS = [
  {key:'army',  label:'Quân đội VN', q:'(site:qdnd.vn OR site:mod.gov.vn OR site:qpvn.vn) when:14d'},
  {key:'tsqct', label:'TSQCT', q:'"Trường Sĩ quan Chính trị" OR "Đại học Chính trị" OR "Trường Đại học Chính trị" when:60d'}
];
const NEWS_PROXIES = [
  u => 'https://api.allorigins.win/raw?url=' + encodeURIComponent(u),
  u => 'https://corsproxy.io/?' + encodeURIComponent(u)
];
let newsItems = [], newsFilter = 'all', newsBusy = false, newsStarted = false, newsUpdated = 0, newsNote = '';

/* -- hàm thuần (dễ kiểm tra) -- */
function newsNorm(title, source, link, date, key){
  title = (title || '').trim(); source = (source || '').trim();
  const i = title.lastIndexOf(' - ');
  if (i > 0) {
    const tail = title.slice(i + 3).trim();
    if (!source) source = tail;
    if (tail === source) title = title.slice(0, i).trim();
  }
  const d = new Date(date);
  return {title, source: source || 'Không rõ nguồn', link: link || '', time: isNaN(d) ? 0 : d.getTime(), key};
}
function newsRel(ms, now){
  if (!ms) return 'Không rõ thời gian';
  const s = Math.max(0, ((now || Date.now()) - ms) / 1000);
  if (s < 60) return 'Vừa xong';
  if (s < 3600) return Math.floor(s / 60) + ' phút trước';
  if (s < 86400) return Math.floor(s / 3600) + ' giờ trước';
  if (s < 86400 * 7) return Math.floor(s / 86400) + ' ngày trước';
  return new Date(ms).toLocaleDateString('vi-VN', {timeZone:'Asia/Ho_Chi_Minh'});
}
function newsExact(ms){
  if (!ms) return '';
  return new Date(ms).toLocaleString('vi-VN', {timeZone:'Asia/Ho_Chi_Minh', hour:'2-digit', minute:'2-digit', hour12:false, day:'2-digit', month:'2-digit', year:'numeric'});
}
function newsMerge(lists){
  const seen = new Set(), out = [];
  lists.flat().sort((a, b) => b.time - a.time).forEach(x => {
    const k = x.title.toLowerCase().replace(/\s+/g, ' ');
    if (!x.title || seen.has(k)) return;
    seen.add(k); out.push(x);
  });
  return out.slice(0, 60);
}

/* -- tải dữ liệu -- */
function newsFetch(url, ms){
  const c = new AbortController(), t = setTimeout(() => c.abort(), ms || 7000);
  return fetch(url, {signal: c.signal}).finally(() => clearTimeout(t));
}
function newsParseXML(text, key){
  const doc = new DOMParser().parseFromString(text, 'text/xml');
  if (doc.querySelector('parsererror')) throw new Error('xml');
  return [...doc.querySelectorAll('item')].map(it => {
    const g = n => { const e = it.getElementsByTagName(n)[0]; return e ? e.textContent : ''; };
    return newsNorm(g('title'), g('source'), g('link'), g('pubDate'), key);
  });
}
async function newsFeed(f){
  try {
    const rs = await newsFetch('?api=news&f=' + f.key, 12000);
    const js = await rs.json();
    if (js && Array.isArray(js.items)) return js.items.map(x => newsNorm(x.title, x.source, x.link, x.time, f.key));
  } catch(e){}
  const url = 'https://news.google.com/rss/search?q=' + encodeURIComponent(f.q) + '&hl=vi&gl=VN&ceid=VN:vi';
  for (const px of NEWS_PROXIES) {
    try {
      const r = await newsFetch(px(url));
      if (!r.ok) continue;
      return newsParseXML(await r.text(), f.key);
    } catch(e){}
  }
  const r = await newsFetch('https://api.rss2json.com/v1/api.json?rss_url=' + encodeURIComponent(url));
  if (!r.ok) throw new Error('rss2json ' + r.status);
  const j = await r.json();
  if (j.status !== 'ok') throw new Error('rss2json');
  return (j.items || []).map(x => {
    const d = /^\d{4}-\d\d-\d\d \d\d:\d\d:\d\d$/.test(x.pubDate || '') ? x.pubDate.replace(' ', 'T') + 'Z' : x.pubDate;
    return newsNorm(x.title, '', x.link, d, f.key);
  });
}
function newsRead(){
  try { const c = JSON.parse(localStorage.getItem(NEWS_KEY) || 'null'); return c && Array.isArray(c.items) ? c : null; } catch(e){ return null; }
}
function newsSave(items){
  try { localStorage.setItem(NEWS_KEY, JSON.stringify({t: Date.now(), items})); } catch(e){}
}

/* -- hiển thị -- */
function newsFoot(){
  const t = newsUpdated ? ' Cập nhật lúc ' + new Date(newsUpdated).toLocaleTimeString('vi-VN', {timeZone:'Asia/Ho_Chi_Minh', hour:'2-digit', minute:'2-digit', hour12:false}) + '.' : '';
  $('#news-foot').textContent = 'Tin tổng hợp từ Google News (Báo QĐND, Bộ Quốc phòng, báo chí khác). Bấm vào tin để đọc ở trang gốc.' + t + (newsNote ? ' ' + newsNote : '') + ' · Bản web v4';
}
function newsMsg(text, withRetry){
  const list = $('#news-list'); list.replaceChildren();
  const li = el('li', 'news-msg', text);
  if (withRetry) {
    const b = el('button', 'btn ghost', 'Thử lại'); b.type = 'button';
    b.addEventListener('click', () => loadNews(true));
    const a = el('a', 'btn ghost', 'Mở Báo QĐND');
    a.href = 'https://www.qdnd.vn/'; a.target = '_blank'; a.rel = 'noopener noreferrer';
    li.append(document.createElement('br'), b, a);
  }
  list.append(li);
}
function renderNews(){
  const list = $('#news-list');
  const items = newsItems.filter(x => newsFilter === 'all' || x.key === newsFilter);
  if (!items.length) { newsMsg('Chưa có tin nào trong mục này.', false); return; }
  list.replaceChildren();
  const labels = {army:'Quân đội VN', tsqct:'TSQCT'};
  items.forEach(x => {
    const li = el('li');
    const a = el('a', 'news-item');
    if (/^https?:\/\//i.test(x.link)) { a.href = x.link; a.target = '_blank'; a.rel = 'noopener noreferrer'; }
    const meta = el('div', 'n-meta');
    meta.append(el('span', 'n-src', x.source), el('span', 'n-tag', labels[x.key] || 'Tin tức'));
    const tm = el('div', 'n-time', ''); tm.dataset.t = x.time;
    tm.textContent = newsRel(x.time) + (x.time ? ' · ' + newsExact(x.time) : '');
    a.append(el('span', 'n-title', x.title), meta, tm);
    li.append(a); list.append(li);
  });
}
function newsTick(){
  document.querySelectorAll('#news-list .n-time').forEach(n => {
    const t = +n.dataset.t; if (t) n.textContent = newsRel(t) + ' · ' + newsExact(t);
  });
}

async function loadNews(force){
  if (newsBusy) return;
  const cache = newsRead();
  if (!force && cache && Date.now() - cache.t < NEWS_TTL) {
    newsItems = cache.items; newsUpdated = cache.t; newsNote = ''; renderNews(); newsFoot(); return;
  }
  newsBusy = true;
  const rb = $('#news-refresh'); rb.classList.add('spin'); rb.disabled = true;
  if (!newsItems.length) newsMsg('Đang tải tin mới nhất…', false);
  const res = await Promise.allSettled(NEWS_FEEDS.map(newsFeed));
  const ok = res.filter(r => r.status === 'fulfilled').map(r => r.value);
  if (ok.length) {
    newsItems = newsMerge(ok); newsUpdated = Date.now(); newsSave(newsItems);
    newsNote = ok.length < NEWS_FEEDS.length ? '(Một nguồn tạm thời chưa tải được.)' : '';
    renderNews();
  } else if (cache) {
    newsItems = cache.items; newsUpdated = cache.t;
    newsNote = '(Không kết nối được, đang hiện tin đã lưu.)'; renderNews();
  } else if (!newsItems.length) {
    newsMsg('Không tải được tin lúc này. Kiểm tra mạng rồi thử lại.', true);
  }
  newsFoot();
  rb.classList.remove('spin'); rb.disabled = false; newsBusy = false;
}

function initNews(){
  if (newsStarted) return; newsStarted = true;
  const box = $('#news');
  if (innerHeight < 620) { box.dataset.collapsed = 'true'; $('#news-toggle').setAttribute('aria-expanded', 'false'); }
  document.querySelectorAll('.chip').forEach(c => c.addEventListener('click', () => {
    newsFilter = c.dataset.f;
    document.querySelectorAll('.chip').forEach(x => x.setAttribute('aria-pressed', String(x === c)));
    renderNews(); $('#news-list').scrollTop = 0;
  }));
  $('#news-refresh').addEventListener('click', () => loadNews(true));
  $('#news-toggle').addEventListener('click', () => {
    const closed = box.dataset.collapsed !== 'true';
    box.dataset.collapsed = String(closed);
    $('#news-toggle').setAttribute('aria-expanded', String(!closed));
  });
  loadNews(false);
  setInterval(() => loadNews(true), NEWS_TTL);
  setInterval(newsTick, 60000);
}


</script>
</body>
</html>
